import time
import requests

def retry_with_backoff(func, max_retries=3, backoff_factor=2):
    """Retry function with exponential backoff."""
    for attempt in range(max_retries):
        try:
            response = func()
            if response.status_code < 500:
                return response

            # Only retry on server errors
            if response.status_code >= 500:
