export function useApiErrorHandler() {
  const { enqueueSnackbar } = useSnackbar();
  const navigate = useNavigate();

  const handleError = useCallback(
    (error: ApiException) => {
      // Handle specific error codes
      switch (error.code) {
        case 'UNAUTHORIZED':
          enqueueSnackbar('Your session has expired. Please sign in again.', {
            variant: 'warning',
          });
          navigate('/login');
          break;

        case 'FORBIDDEN':
          enqueueSnackbar('You don't have permission to perform this action.', {
            variant: 'error',
          });
          break;

        case 'NOT_FOUND':
          enqueueSnackbar('The requested resource was not found.', {
            variant: 'error',
          });
          navigate('/404');
          break;

        case 'VALIDATION_ERROR':
          // Validation errors handled inline in forms
          break;

        case 'RATE_LIMIT_EXCEEDED':
          enqueueSnackbar(
            'Rate limit exceeded. Please try again in a few moments.',
            {
              variant: 'warning',
              autoHideDuration: 10000,
            }
          );
          break;

        case 'SERVER_ERROR':
          enqueueSnackbar(
            'A server error occurred. Please try again or contact support.',
            {
              variant: 'error',
            }
          );
          break;

        case 'NETWORK_ERROR':
          enqueueSnackbar(
            'Network error. Please check your connection and try again.',
            {
              variant: 'error',
            }
          );
          break;

        default:
          enqueueSnackbar(error.message || 'An error occurred', {
            variant: 'error',
          });
      }
    },
    [enqueueSnackbar, navigate]
  );

  return { handleError };
}

