};

export function formatDate(
  date: Date | string,
  formatStr: string = 'PP',
  locale?: string
): string {
  const currentLocale = locale || i18n.language;
  const dateFnsLocale = localeMap[currentLocale] || enUS;
  return format(new Date(date), formatStr, { locale: dateFnsLocale });
}

