  date: Date | string,
  locale?: string
): string {
  const currentLocale = locale || i18n.language;
  const dateFnsLocale = localeMap[currentLocale] || enUS;
  return formatDistance(new Date(date), new Date(), {
    locale: dateFnsLocale,
    addSuffix: true,
  });
}

