    "apiVersion": "odcs/v3",
    "kind": "DataContract",
    "id": "example-contract",
    "name": "Example Contract",
    "version": "1.0.0",
    "schema": {
        "fields": [
            {
                "name": "id",
                "type": "string",
                "nullable": False
            },
            {
                "name": "email",
                "type": "string",
                "format": "email",
                "nullable": True
            }
        ]
    },
    "support": [
