            "name": "Support Team"
        }
    ],
    "servers": [
        {
            "type": "s3",
            "url": "s3://bucket/data"
        }
    ]
}

def create_contract():
    """Create a contract via API."""
    url = f"{API_BASE_URL}/contracts/"

    payload = {
        "original_raw": json.dumps(contract_data),
        "original_format": "JSON"
    }

    try:
        response = requests.post(url, headers=headers, json=payload)
        response.raise_for_status()

        contract = response.json()
        print(f"Contract created successfully!")
        print(f"Contract ID: {contract['id']}")
        print(f"Status: {contract['status']}")
        print(f"Normalization Status: {contract['normalization_status']}")

        return contract
    except requests.exceptions.HTTPError as e:
        error_data = response.json()
        error = error_data.get('error', {})
        print(f"Error creating contract: {error.get('message')}")
        print(f"Error code: {error.get('code')}")
        if 'details' in error and 'field_errors' in error['details']:
            for field_error in error['details']['field_errors']:
                print(f"  - {field_error['field']}: {field_error['message']}")
        raise
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")
        raise

if __name__ == "__main__":
    create_contract()

